#include "opentdf.h"
#include <stdio.h>
#include <string.h>

otdf_options options = OTDF_OPTIONS_INIT;
options.client_id = client_id;
options.client_secret = client_secret;
otdf_sdk *client = NULL;
otdf_error error = {0};
otdf_owned_bytes archive = {0}, plaintext = {0};
int status = otdf_sdk_new(platform_url, &options, NULL, &client, &error);
if (status == 0) {
    const char *attributes[] = {attribute_fqn};
    otdf_tdf_options encryption = OTDF_TDF_OPTIONS_INIT;
    encryption.attributes = attributes;
    encryption.attribute_count = 1;
    encryption.mime_type = "text/plain";
    encryption.metadata = "{\"name\":\"note.txt\"}";
    const char *note = "A confidential note";
    status = otdf_encrypt_bytes(client,
        (otdf_bytes){(const uint8_t *)note, strlen(note)},
        &encryption, NULL, &archive, &error);
}
if (status == 0) {
    status = otdf_decrypt_bytes(client,
        (otdf_bytes){archive.data, archive.length},
        NULL, NULL, &plaintext, &error);
}
if (status == 0) {
    fwrite(plaintext.data, 1, plaintext.length, stdout);
} else {
    fprintf(stderr, "%s\n", error.message);
}
otdf_bytes_free(&plaintext);
otdf_bytes_free(&archive);
otdf_error_free(&error);
if (client != NULL) {
    otdf_sdk_close(client, NULL);
    otdf_sdk_free(client);
}

