#include <stdio.h>

int provide_access_token(void *state,
    const uint8_t *name, size_t name_length,
    const uint8_t *payload, size_t payload_length,
    const atomic_bool *canceled, gxc_value *response);

otdf_options options = OTDF_OPTIONS_INIT;
options.token_provider = provide_access_token;
options.token_provider_state = auth_state;
otdf_sdk *client = NULL;
otdf_error error = {0};
otdf_access_token token = {0};
int status = otdf_sdk_new(platform_url, &options, NULL, &client, &error);
if (status == 0) {
    status = otdf_auth_access_token(client, NULL, &token, &error);
}
if (status == 0) {
    printf("Auth scheme: %s\n", token.scheme);
} else {
    fprintf(stderr, "%s\n", error.message);
}
otdf_access_token_free(&token);
otdf_error_free(&error);
if (client != NULL) {
    otdf_sdk_close(client, NULL);
    otdf_sdk_free(client);
}

